def contar_rotulos(rotulos):
    out = {}
    for rotulo in rotulos:
        chave = rotulo.strip().casefold()
        out[chave] = out.get(chave,0)+1
    return out
entrada = [" FÍSICA ","física","Código"]
assert contar_rotulos(entrada)=={"física":2,"código":1}
assert entrada[0]==" FÍSICA "
